package edu.riara.edp.week07;
import javafx.application.Application;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.input.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class DragDropDemo extends Application {public void start(Stage s){Label from=new Label("Drag this text"),to=new Label("Drop here");from.setOnDragDetected(e->{Dragboard db=from.startDragAndDrop(TransferMode.COPY);ClipboardContent content=new ClipboardContent();content.putString(from.getText());db.setContent(content);e.consume();});to.setOnDragOver(e->{if(e.getDragboard().hasString())e.acceptTransferModes(TransferMode.COPY);e.consume();});to.setOnDragDropped(e->{boolean ok=e.getDragboard().hasString();if(ok)to.setText(e.getDragboard().getString());e.setDropCompleted(ok);e.consume();});HBox root=new HBox(45,from,to);s.setScene(new Scene(root,450,200));s.show();}public static void main(String[]a){launch(a);}}